 def test_actual_factory_public_body_roundtrip_and_readonly_scope(self):
  source,sha=refresh.program(ScreenTests().record(),refresh.PAIR_EXPECTED);tree=ast.parse(source)
  encoded=next(n.value.value for n in tree.body if isinstance(n,ast.Assign)and any(isinstance(t,ast.Name)and t.id=='ENCODED'for t in n.targets))
  bootstrap=base64.b64decode(encoded).decode('utf-16le');packed=re.search("FromBase64String\\('([^']+)'\\)",bootstrap).group(1);full=gzip.decompress(base64.b64decode(packed));plain=refresh.body(refresh.PAIR_EXPECTED)
  self.assertTrue(full.decode().endswith(plain));self.assertIn(str(len(full)),bootstrap);self.assertIn(hashlib.sha256(full).hexdigest(),bootstrap);self.assertEqual(hashlib.sha256(plain.encode('utf-16le')).hexdigest(),sha);self.assertLess(len(encoded),30000);self.assertLess(len(full),65536)
  for forbidden in ('Start-Process','Start-ScheduledTask','Register-ScheduledTask','LogonUser(', 'SetValue(', 'SendInput(','.InvokeVerb('):self.assertNotIn(forbidden,plain)
  self.assertIn('$engine.OpenDatabase($candidate,0)',plain);self.assertIn('$view.Close()',plain);self.assertIn('FILE_DRIFT',plain);self.assertIn('FinalReleaseComObject',plain)
  with patch.object(refresh.installed,'body',return_value=refresh.installed.body(refresh.PAIR_EXPECTED)+'\nforeign'):
   # A source-authenticated module alone does not authorize substituted factories.
   # Existing inner factory's exact body catalog must still reject actual changes.
   with self.assertRaises(ValueError):refresh.program(ScreenTests().record(),refresh.PAIR_EXPECTED)
