class HeldMsiTests(HistoryCase):
 @unittest.skipIf(sys.platform=='win32','POSIX FD-first upload artifact holder')
 def test_exact_fd_hash_named_exchange_rejected_before_transport(self):
  import os
  with tempfile.TemporaryDirectory()as directory:
   root=Path(directory).resolve();p=root/'base.msi';payload=b'public-holder-fixture';p.write_bytes(payload)
   with patch.object(refresh,'BASE_SIZE',len(payload)),patch.object(refresh,'BASE_HASH',hashlib.sha256(payload).hexdigest()):
    with self.assertRaisesRegex(ValueError,'msi-generation'):
     with refresh._held_msi(p)as(stream,pin,verify):
      self.assertEqual(stream.read(),payload);other=root/'replacement';other.write_bytes(payload);os.replace(other,p);verify()
    with refresh._held_msi(p)as(stream,pin,verify):self.assertEqual(stream.read(),payload);verify()
    p.write_bytes(b'X'*len(payload))
    with self.assertRaisesRegex(ValueError,'msi-hash'):
     with refresh._held_msi(p):self.fail('wrong hash admitted')

