 @unittest.skipIf(sys.platform=='win32','Actual POSIX resource admission wrapper')
 def test_actual_generated_budget_guard_refuses_before_any_writer_execution(self):
  import subprocess
  source,_=refresh.stage_program(UploadTests().record());tree=ast.parse(source);operation=tree.body[-1]
  # Exact production statements between original guards and the writer namespace.
  start=next(i for i,n in enumerate(operation.body)if isinstance(n,ast.Import)and n.names[0].name=='resource')
  end=next(i for i,n in enumerate(operation.body)if isinstance(n,ast.Assign)and any(isinstance(t,ast.Name)and t.id=='_transfer_scope'for t in n.targets))
  guard=ast.unparse(ast.Module(body=operation.body[start:end],type_ignores=[]))
  script="import resource,json,sys;resource.setrlimit(resource.RLIMIT_FSIZE,(4096,4096))\ndef need(v,p):\n if not v:raise ValueError(p)\n"+guard+"\nprint('UNSAFE_WRITER_ENTERED')\n"
  value=subprocess.run([sys.executable,'-c',script],capture_output=True,timeout=5)
  self.assertNotEqual(value.returncode,0);self.assertNotIn(b'UNSAFE_WRITER_ENTERED',value.stdout);self.assertIn(b'host-file-size-limit',value.stderr);self.assertIn(b'4096',value.stderr)
  limits_source,_=refresh.stage_program(UploadTests().record(),'limits');self.assertNotIn(repr(refresh.transfer._REMOTE_STAGE),limits_source)
  self.assertNotIn('setrlimit',source);self.assertNotIn('setrlimit',limits_source)

