 def pieces(self,template):
  functions=template[template.index('function WriteNew'):template.index('try{\n $identity=')]
  wait=template[template.index(' if(-not $installer.WaitForExit'):template.index(" $phase='readback';")]
  catch=template.rsplit('}catch{',1)[1] # Includes actual finally/held-handle disposal.
  return functions,wait,catch
