class StdinCollectorCausalTests(HistoryCase):
 @unittest.skipUnless(__import__('shutil').which('powershell'),'Actual Windows managed pipe collection required')
 def test_actual_collector_timeout_overflow_and_blocked_pipe_retains_raw(self):
  import subprocess
  with tempfile.TemporaryDirectory(prefix='cp117-collector-')as parent:
   ps=lambda v:"'"+v.replace("'","''")+"'"
   prefix="$ErrorActionPreference='Stop';Add-Type -TypeDefinition "+ps(STDIN_CAPTURE_CS)+" -ReferencedAssemblies @('System','System.Core');\n"+STDIN_CAPTURE_WRITER_PS
   script=prefix+"$parent="+ps(str(Path(parent)))+";\n"
   for mode,command in [('timeout','/c echo PUBLIC & ping -n 4 127.0.0.1 >NUL'),('overflow','/c for /L %i in (1,1,10000) do @echo PUBLIC')]:
    root=str(Path(parent)/mode)
    script+="$caseRoot="+ps(root)+";[void][IO.Directory]::CreateDirectory($caseRoot);$start=[Diagnostics.ProcessStartInfo]::new('cmd.exe',"+ps(command)+");$start.UseShellExecute=$false;$start.RedirectStandardOutput=$true;$start.RedirectStandardError=$true;$child=[Diagnostics.Process]::Start($start);$birth=$child.StartTime.ToUniversalTime().ToFileTimeUtc().ToString();try{\n"
    # Execute exact lost-boundary predicate before the real current collector on same child.
    script+="try{\n"+STDIN_OLD_COLLECTION_PS.replace('WaitForExit(20000)','WaitForExit(200)')+"}catch{};if([IO.File]::Exists((Join-Path $caseRoot 'stdout.private'))){throw 'OLD_RAW_UNEXPECTED'};\n"
    script+="$outCapture=[Cp117StdinCapture]::new($child.StandardOutput.BaseStream,4096);$errCapture=[Cp117StdinCapture]::new($child.StandardError.BaseStream,16384);try{\n"+STDIN_CHILD_COLLECTION_PS.replace('WaitForExit(20000)','WaitForExit(200)'if mode=='timeout'else'WaitForExit(20000)')+"}catch{};\n"
    script+="if(-not [IO.File]::Exists((Join-Path $caseRoot 'stdout.private')) -or -not [IO.File]::Exists((Join-Path $caseRoot 'stderr.private')) -or -not [IO.File]::Exists((Join-Path $caseRoot 'collection.json'))){throw 'NEW_RAW_MISSING'};$record=Get-Content -Raw (Join-Path $caseRoot 'collection.json')|ConvertFrom-Json;"
    if mode=='timeout':script+="if($record.completed -or $record.stdoutBytes -le 0 -or $null -ne $record.exitCode){throw 'TIMEOUT_PARTIAL'};"
    else:script+="if(-not $record.completed -or -not $record.stdoutOverflow -or $record.stdoutBytes -ne 4096){throw 'OVERFLOW_BOUND'};"
    script+="if(-not $child.WaitForExit(6000)){throw 'NATURAL_CHILD_END_UNKNOWN'};[void]$outCapture.Join(2000);[void]$errCapture.Join(2000)}finally{$child.Dispose()}\n"
   script+="[Console]::Out.WriteLine('COLLECTOR_CAUSAL_PASS')"
   result=subprocess.run(['powershell','-NoProfile','-NonInteractive','-EncodedCommand',base64.b64encode(script.encode('utf-16le')).decode()],capture_output=True,timeout=25);self.assertEqual(result.returncode,0,result.stderr.decode(errors='replace'));self.assertEqual(result.stdout.strip(),b'COLLECTOR_CAUSAL_PASS')

