 @unittest.skipUnless(__import__('sys').platform.startswith('linux'),'Actual Linux per-argument E2BIG boundary required')
 def test_actual_old_command_argument_linux_e2big_without_interpreting_guest_code(self):
  from agent_tools import windows_credential_probe_ssh as transport
  import subprocess,sys,errno
  # Single physical-line Python comment prevents any source execution if the
  # kernel unexpectedly accepts it; exact legacy argument is preserved inside.
  argument='0#'+transport._remote_command(self.public())[2]
  self.assertGreater(len(argument.encode()),131072);self.assertLess(len(argument.encode()),262144)
