SHORTCUT_STDIN_ORIGINAL_STREAM_SOURCE="def _stream(argv,capture,diagnostic,nonce,sha,qemu,secret):\n    _sources()\n    if hashlib.sha256(inspect.getsource(role._stream).encode()).hexdigest()!=ROLE_STREAM_SHA:raise ValueError('provider-fixed-stream')\n    import selectors,subprocess\n    r=login.guest.recovery\n    if secret is not None and(not isinstance(secret,bytes)or len(secret)>512):raise ValueError('gui-private-input-bound')\n    process=subprocess.Popen(argv,stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE)\n    selector=selectors.DefaultSelector();chunks={'stdout':bytearray(),'stderr':bytearray()};pending=bytearray();events=[];child=None;deadline=time.monotonic()+60\n    selector.register(process.stdout,selectors.EVENT_READ,'stdout');selector.register(process.stderr,selectors.EVENT_READ,'stderr')\n    try:\n        if secret is not None:\n            process.stdin.write(len(secret).to_bytes(4,'big')+secret);process.stdin.flush();secret=b''\n        while selector.get_map():\n            if time.monotonic()>=deadline:raise ValueError('gui-observer-deadline')\n            for key,_ in selector.select(.25):\n                data=os.read(key.fileobj.fileno(),4096)\n                if not data:selector.unregister(key.fileobj);continue\n                chunks[key.data].extend(data)\n                if len(chunks[key.data])>262144:raise ValueError('gui-observer-byte-cap')\n                if key.data=='stderr':\n                    pending.extend(data)\n                    while b'\\n'in pending:\n                        line,rest=pending.split(b'\\n',1);pending=bytearray(rest)\n                        if not line.startswith(b'CP117-OBSERVE '):continue\n                        event=json.loads(line[14:])\n                        if any(event.get(k)!=v for k,v in{'diagnosticId':diagnostic,'nonce':nonce,'sourceSha256':sha,'qemu':qemu}.items()):raise ValueError('gui-event-binding')\n                        if event['kind']=='submitted':\n                            if child is not None or type(event.get('pid'))is not int or event['pid']<=0:raise ValueError('gui-one-child')\n                            child=event['pid']\n                        elif event['kind']in('poll','terminal'):\n                            if child is None or event.get('pid')!=child:raise ValueError('gui-same-child')\n                        elif event['kind']!='exception':raise ValueError('gui-event-kind')\n                        pin=capture.create(diagnostic+'-event-%d.json'%len(events),json.dumps(event,sort_keys=True).encode());os.fsync(capture.fd);events.append({'event':event,'pin':pin})\n                        if event['kind']=='submitted':\n                            ack=r._digest({'diagnosticId':diagnostic,'nonce':nonce,'sourceSha256':sha,'pid':child});process.stdin.write((ack+'\\n').encode());process.stdin.flush()\n        if process.wait(timeout=max(.001,deadline-time.monotonic()))!=0:raise ValueError('gui-observer-exit')\n        value=json.loads(chunks['stdout']);return value,events\n    except BaseException as e:\n        e.events=events\n        if process.poll()is None:process.kill()  # Only this local observer, never VM/app.\n        process.wait(timeout=3);raise\n    finally:\n        capture.create(diagnostic+'-transport.stdout.private',bytes(chunks['stdout']));capture.create(diagnostic+'-transport.stderr.private',bytes(chunks['stderr']));os.fsync(capture.fd)\n        selector.close();process.stdin.close();process.stdout.close();process.stderr.close()"

SHORTCUT_STDIN_STREAM_SOURCE="def _source_stream(argv,capture,diagnostic,nonce,sha,qemu,source_frame):\n    _sources()\n    if hashlib.sha256(inspect.getsource(role._stream).encode()).hexdigest()!=ROLE_STREAM_SHA:raise ValueError('provider-fixed-stream')\n    import selectors,subprocess\n    r=login.guest.recovery\n    if type(source_frame)is not bytes or not 13<len(source_frame)<=65549 or source_frame[:9]!=b'CP117SRC1' or int.from_bytes(source_frame[9:13],'big')!=len(source_frame)-13:raise ValueError('source-frame-bound')\n    process=subprocess.Popen(argv,stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE)\n    selector=selectors.DefaultSelector();chunks={'stdout':bytearray(),'stderr':bytearray()};pending=bytearray();events=[];child=None;deadline=time.monotonic()+60\n    retained=False;outbound=bytearray(source_frame);birth=None\n    def retain():\n        nonlocal retained\n        if retained:return\n        capture.create(diagnostic+'-transport.stdout.private',bytes(chunks['stdout']));capture.create(diagnostic+'-transport.stderr.private',bytes(chunks['stderr']))\n        capture.create(diagnostic+'-local-status.json',json.dumps({'pid':process.pid,'birth':birth,'exitCode':process.poll(),'sourceFrameWritten':not outbound,'stdoutBytes':len(chunks['stdout']),'stderrBytes':len(chunks['stderr'])},sort_keys=True).encode());os.fsync(capture.fd);retained=True\n    try:\n        birth=_process_generation(process.pid)\n        if birth is None:\n            capture.create(diagnostic+'-local-child.json',json.dumps({'pid':process.pid,'birth':None,'uid':os.getuid()},sort_keys=True).encode());os.fsync(capture.fd)\n            process.stdin.close()\n            for name,pipe in(('stdout',process.stdout),('stderr',process.stderr)):\n                os.set_blocking(pipe.fileno(),False);selector.register(pipe,selectors.EVENT_READ,name)\n            drain_deadline=min(deadline,time.monotonic()+1)\n            while selector.get_map() and time.monotonic()<drain_deadline:\n                for key,_ in selector.select(min(.05,max(0,drain_deadline-time.monotonic()))):\n                    try:data=os.read(key.fileobj.fileno(),4096)\n                    except BlockingIOError:continue\n                    if not data:selector.unregister(key.fileobj);continue\n                    remaining=262144-len(chunks[key.data]);chunks[key.data].extend(data[:remaining])\n                    if len(data)>remaining:raise ValueError('gui-observer-byte-cap')\n            retain();raise ValueError('local-observer-birth')\n        capture.create(diagnostic+'-local-child.json',json.dumps({'pid':process.pid,'birth':birth,'uid':os.getuid()},sort_keys=True).encode());os.fsync(capture.fd)\n        outbound=bytearray(source_frame);source_frame=b'';acknowledged=False\n        os.set_blocking(process.stdin.fileno(),False)\n        selector.register(process.stdin,selectors.EVENT_WRITE,'stdin')\n        selector.register(process.stdout,selectors.EVENT_READ,'stdout');selector.register(process.stderr,selectors.EVENT_READ,'stderr')\n        while selector.get_map():\n            if time.monotonic()>=deadline:raise ValueError('gui-observer-deadline')\n            for key,_ in selector.select(.25):\n                if key.data=='stdin':\n                    try:written=os.write(process.stdin.fileno(),outbound[:4096])\n                    except BlockingIOError:continue\n                    if written<=0:raise ValueError('source-frame-write')\n                    del outbound[:written]\n                    if not outbound:\n                        selector.unregister(process.stdin)\n                        if acknowledged:process.stdin.close()\n                    continue\n                data=os.read(key.fileobj.fileno(),4096)\n                if not data:selector.unregister(key.fileobj);continue\n                remaining=262144-len(chunks[key.data]);chunks[key.data].extend(data[:remaining])\n                if len(data)>remaining:raise ValueError('gui-observer-byte-cap')\n                if key.data=='stderr':\n                    pending.extend(data)\n                    while b'\\n'in pending:\n                        line,rest=pending.split(b'\\n',1);pending=bytearray(rest)\n                        if not line.startswith(b'CP117-OBSERVE '):continue\n                        capture.create(diagnostic+'-event-raw-%d.private'%len(events),bytes(line));os.fsync(capture.fd)\n                        event=json.loads(line[14:])\n                        if any(event.get(k)!=v for k,v in{'diagnosticId':diagnostic,'nonce':nonce,'sourceSha256':sha,'qemu':qemu}.items()):raise ValueError('gui-event-binding')\n                        if event['kind']=='submitted':\n                            if child is not None or type(event.get('pid'))is not int or event['pid']<=0:raise ValueError('gui-one-child')\n                            child=event['pid']\n                        elif event['kind']in('poll','terminal'):\n                            if child is None or event.get('pid')!=child:raise ValueError('gui-same-child')\n                        elif event['kind']!='exception':raise ValueError('gui-event-kind')\n                        pin=capture.create(diagnostic+'-event-%d.json'%len(events),json.dumps(event,sort_keys=True).encode());os.fsync(capture.fd);events.append({'event':event,'pin':pin})\n                        if event['kind']=='submitted':\n                            ack=r._digest({'diagnosticId':diagnostic,'nonce':nonce,'sourceSha256':sha,'pid':child});outbound.extend((ack+'\\n').encode());acknowledged=True\n                            if process.stdin.closed:raise ValueError('source-frame-ack-channel')\n                            try:selector.get_key(process.stdin)\n                            except KeyError:selector.register(process.stdin,selectors.EVENT_WRITE,'stdin')\n        code=process.wait(timeout=max(.001,deadline-time.monotonic()));retain()\n        if code!=0:raise ValueError('gui-observer-exit')\n        value=json.loads(chunks['stdout']);return value,events\n    except BaseException as e:\n        e.events=events\n        retain();capture.create(diagnostic+'-local-error.json',json.dumps({'phase':'stream','exceptionType':type(e).__name__,'pid':process.pid,'birth':birth,'exitCode':process.poll()},sort_keys=True).encode());os.fsync(capture.fd);raise\n    finally:\n        retain();selector.close();process.stdin.close();process.stdout.close();process.stderr.close()"

SHORTCUT_STDIN_COMMAND_SOURCE='def _stdin_shortcut_command(program):\n import gzip,hashlib,shlex\n if type(program)is not str:raise ValueError(\'shortcut-source-type\')\n public=program.encode(\'utf-8\')\n if not 0<len(public)<=131072:raise ValueError(\'shortcut-source-bound\')\n packed=gzip.compress(public,mtime=0)\n if not 0<len(packed)<=65536:raise ValueError(\'shortcut-packed-bound\')\n bootstrap="import sys,zlib,hashlib\\ndef _sc_read(n):\\n b=bytearray()\\n while len(b)<n:\\n  v=sys.stdin.buffer.read(min(4096,n-len(b)))\\n  if not v:raise ValueError(\'SHORTCUT_SOURCE_EOF\')\\n  b.extend(v)\\n return bytes(b)\\n_sc_header=_sc_read(13)\\nif _sc_header[:9]!=b\'CP117SRC1\' or int.from_bytes(_sc_header[9:],\'big\')!="+str(len(packed))+":raise ValueError(\'SHORTCUT_SOURCE_HEADER\')\\n_sc_p=_sc_read("+str(len(packed))+");_sc_d=zlib.decompressobj(31);_sc_b=_sc_d.decompress(_sc_p,"+str(len(public)+1)+")\\nif len(_sc_b)!="+str(len(public))+" or not _sc_d.eof or _sc_d.unused_data or _sc_d.unconsumed_tail or hashlib.sha256(_sc_b).hexdigest()!="+repr(hashlib.sha256(public).hexdigest())+":raise ValueError(\'SHORTCUT_ENVELOPE\')\\nexec(compile(_sc_b.decode(\'utf-8\',\'strict\'),\'<string>\',\'exec\'))"\n command=(\'python3\',\'-c\',\'exec(\'+repr(bootstrap)+\')\')\n if max(len(x.encode())for x in command)>4096 or len(\' \'.join(shlex.quote(x)for x in command).encode())>4096:raise ValueError(\'shortcut-bootstrap-bound\')\n return command,b\'CP117SRC1\'+len(packed).to_bytes(4,\'big\')+packed\n'

SHORTCUT_LOCAL_BIRTH_SOURCE='def _process_generation(pid: int) -> str | None:\n    """Return a platform-native process generation marker, never PID alone."""\n    if platform.system() == "Darwin":\n        # libproc\'s start timeval distinguishes a reused PID even when ``ps``\n        # renders both processes in the same second.\n        import ctypes\n\n        class ProcBsdInfo(ctypes.Structure):\n            _fields_ = [("flags", ctypes.c_uint32), ("status", ctypes.c_uint32),\n                       ("xstatus", ctypes.c_uint32), ("pid", ctypes.c_uint32),\n                       ("ppid", ctypes.c_uint32), ("uid", ctypes.c_uint32), ("gid", ctypes.c_uint32),\n                       ("ruid", ctypes.c_uint32), ("rgid", ctypes.c_uint32), ("svuid", ctypes.c_uint32),\n                       ("svgid", ctypes.c_uint32), ("reserved", ctypes.c_uint32),\n                       ("comm", ctypes.c_char * 16), ("name", ctypes.c_char * 32),\n                       ("nfiles", ctypes.c_uint32), ("pgid", ctypes.c_uint32), ("pjobc", ctypes.c_uint32),\n                       ("tdev", ctypes.c_uint32), ("tpgid", ctypes.c_uint32), ("nice", ctypes.c_int32),\n                       ("startSeconds", ctypes.c_uint64), ("startMicroseconds", ctypes.c_uint64)]\n        try:\n            info = ProcBsdInfo()\n            received = ctypes.CDLL("/usr/lib/libproc.dylib").proc_pidinfo(\n                pid, 3, 0, ctypes.byref(info), ctypes.sizeof(info))\n            if received != ctypes.sizeof(info) or info.pid != pid or not info.startSeconds:\n                return None\n            return f"darwin:{info.startSeconds}:{info.startMicroseconds}"\n        except (OSError, AttributeError):\n            return None\n    try:\n        fields = Path(f"/proc/{pid}/stat").read_text(encoding="utf-8").rsplit(") ", 1)[1].split()\n        return f"linux:{fields[19]}"\n    except (FileNotFoundError, IndexError, OSError):\n        return None'

