  self.assertEqual(ast.dump(node,include_attributes=False),ast.dump(ast.parse(SHORTCUT_STDIN_ORIGINAL_STREAM_SOURCE).body[0],include_attributes=False))
  source=SHORTCUT_STDIN_STREAM_SOURCE
