  self.assertIsNone(error);self.assertEqual(answer[0],{'state':'observed','ackBound':True});self.assertEqual(len(answer[1]),1);self.assertEqual(self.actual_parser_boundaries,['event-raw-before-parse','terminal-raw-before-parse'])
