SHORTCUT_STDIN_UNKNOWN_BIRTH_OLD_SOURCE="def _source_stream(argv,capture,diagnostic,nonce,sha,qemu,source_frame):\n    _sources()\n    if hashlib.sha256(inspect.getsource(role._stream).encode()).hexdigest()!=ROLE_STREAM_SHA:raise ValueError('provider-fixed-stream')\n    import selectors,subprocess\n    r=login.guest.recovery\n    if type(source_frame)is not bytes or not 13<len(source_frame)<=65549 or source_frame[:9]!=b'CP117SRC1' or int.from_bytes(source_frame[9:13],'big')!=len(source_frame)-13:raise ValueError('source-frame-bound')\n    process=subprocess.Popen(argv,stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE)\n    selector=selectors.DefaultSelector();chunks={'stdout':bytearray(),'stderr':bytearray()};pending=bytearray();events=[];child=None;deadline=time.monotonic()+60\n    retained=False;outbound=bytearray(source_frame);birth=None\n    def retain():\n        nonlocal retained\n        if retained:return\n        capture.create(diagnostic+'-transport.stdout.private',bytes(chunks['stdout']));capture.create(diagnostic+'-transport.stderr.private',bytes(chunks['stderr']))\n        capture.create(diagnostic+'-local-status.json',json.dumps({'pid':process.pid,'birth':birth,'exitCode':process.poll(),'sourceFrameWritten':not outbound,'stdoutBytes':len(chunks['stdout']),'stderrBytes':len(chunks['stderr'])},sort_keys=True).encode());os.fsync(capture.fd);retained=True\n    try:\n        birth=_process_generation(process.pid)\n        if birth is None:\n            process.stdin.close();process.stdout.close();process.stderr.close();retain();raise ValueError('local-observer-birth')\n        capture.create(diagnostic+'-local-child.json',json.dumps({'pid':process.pid,'birth':birth,'uid':os.getuid()},sort_keys=True).encode());os.fsync(capture.fd)\n        outbound=bytearray(source_frame);source_frame=b'';acknowledged=False\n        os.set_blocking(process.stdin.fileno(),False)\n        selector.register(process.stdin,selectors.EVENT_WRITE,'stdin')\n        selector.register(process.stdout,selectors.EVENT_READ,'stdout');selector.register(process.stderr,selectors.EVENT_READ,'stderr')\n        while selector.get_map():\n            if time.monotonic()>=deadline:raise ValueError('gui-observer-deadline')\n            for key,_ in selector.select(.25):\n                if key.data=='stdin':\n                    try:written=os.write(process.stdin.fileno(),outbound[:4096])\n                    except BlockingIOError:continue\n                    if written<=0:raise ValueError('source-frame-write')\n                    del outbound[:written]\n                    if not outbound:\n                        selector.unregister(process.stdin)\n                        if acknowledged:process.stdin.close()\n                    continue\n                data=os.read(key.fileobj.fileno(),4096)\n                if not data:selector.unregister(key.fileobj);continue\n                remaining=262144-len(chunks[key.data]);chunks[key.data].extend(data[:remaining])\n                if len(data)>remaining:raise ValueError('gui-observer-byte-cap')\n                if key.data=='stderr':\n                    pending.extend(data)\n                    while b'\\n'in pending:\n                        line,rest=pending.split(b'\\n',1);pending=bytearray(rest)\n                        if not line.startswith(b'CP117-OBSERVE '):continue\n                        capture.create(diagnostic+'-event-raw-%d.private'%len(events),bytes(line));os.fsync(capture.fd)\n                        event=json.loads(line[14:])\n                        if any(event.get(k)!=v for k,v in{'diagnosticId':diagnostic,'nonce':nonce,'sourceSha256':sha,'qemu':qemu}.items()):raise ValueError('gui-event-binding')\n                        if event['kind']=='submitted':\n                            if child is not None or type(event.get('pid'))is not int or event['pid']<=0:raise ValueError('gui-one-child')\n                            child=event['pid']\n                        elif event['kind']in('poll','terminal'):\n                            if child is None or event.get('pid')!=child:raise ValueError('gui-same-child')\n                        elif event['kind']!='exception':raise ValueError('gui-event-kind')\n                        pin=capture.create(diagnostic+'-event-%d.json'%len(events),json.dumps(event,sort_keys=True).encode());os.fsync(capture.fd);events.append({'event':event,'pin':pin})\n                        if event['kind']=='submitted':\n                            ack=r._digest({'diagnosticId':diagnostic,'nonce':nonce,'sourceSha256':sha,'pid':child});outbound.extend((ack+'\\n').encode());acknowledged=True\n                            if process.stdin.closed:raise ValueError('source-frame-ack-channel')\n                            try:selector.get_key(process.stdin)\n                            except KeyError:selector.register(process.stdin,selectors.EVENT_WRITE,'stdin')\n        code=process.wait(timeout=max(.001,deadline-time.monotonic()));retain()\n        if code!=0:raise ValueError('gui-observer-exit')\n        value=json.loads(chunks['stdout']);return value,events\n    except BaseException as e:\n        e.events=events\n        retain();capture.create(diagnostic+'-local-error.json',json.dumps({'phase':'stream','exceptionType':type(e).__name__,'pid':process.pid,'birth':birth,'exitCode':process.poll()},sort_keys=True).encode());os.fsync(capture.fd);raise\n    finally:\n        retain();selector.close();process.stdin.close();process.stdout.close();process.stderr.close()"

