SHORTCUT_PACKET_VALIDATOR_SOURCE='def _validate_shortcut_packet(source,sha,body,task,nonce,correlation,helper_bytes):\n    import ast,base64,gzip,hashlib,re\n    tree=ast.parse(source)\n    values={n.targets[0].id:ast.literal_eval(n.value) for n in tree.body if isinstance(n,ast.Assign) and len(n.targets)==1 and isinstance(n.targets[0],ast.Name) and n.targets[0].id in (\'D\',\'NONCE\',\'BODY_SHA\',\'ENCODED\')}\n    if values.get(\'D\')!=correlation or values.get(\'NONCE\')!=nonce or values.get(\'BODY_SHA\')!=sha or sha!=hashlib.sha256(body.encode(\'utf-16le\')).hexdigest():raise ValueError(\'shortcut-public-binding\')\n    packets=[n for n in ast.walk(tree) if isinstance(n,ast.Dict) for k,n in zip(n.keys,n.values) if isinstance(k,ast.Constant) and k.value==\'input-data\']\n    if len(packets)!=1 or not isinstance(packets[0],ast.Constant) or type(packets[0].value)is not str:raise ValueError(\'shortcut-packet-catalogue\')\n    packet=base64.b64decode(packets[0].value,validate=True)\n    full=("[Console]::Out.WriteLine((\'CP117-READ "+nonce+" "+sha+" \'+$PID))\\n"+body).encode(\'utf-8\')\n    task_bytes=task.encode(\'utf-8\');size=int.from_bytes(packet[:4],\'little\')\n    if not 0<len(full)<=65536 or not 0<len(task_bytes)<=65536 or size!=len(full) or packet!=len(full).to_bytes(4,\'little\')+full+task_bytes:raise ValueError(\'shortcut-packet-bytes\')\n    digest=hashlib.sha256(task_bytes).hexdigest()\n    consumers=re.findall(r"(?:\\$cp117TaskBytes|\\$v)\\.Length -ne ([0-9]+)",body)\n    task_region=body[body.index(\'$cp117TaskInput=\'):];hashes=re.findall(r"(?:-cne \'+|sourceSha256=\'|taskSourceSha256=\')([0-9a-f]{64})",task_region)\n    # Includes stdin, scheduled-action decoder, durable intent and submission.\n    if consumers!=[str(len(task_bytes)),str(len(task_bytes))] or hashes[-4:]!=[digest]*4 or len(hashes)!=4:raise ValueError(\'shortcut-task-binding\')\n    if "$corr=\'"+correlation+"\'" not in task or "$nonce=\'"+nonce+"\'" not in task:raise ValueError(\'shortcut-task-identity\')\n    action=re.search(r"\\$cp117ActionBootstrap=\'((?:[^\']|\'\')*)\'\\+\\$cp117Packed\\+\'((?:[^\']|\'\')*)\';\\$cp117ActionEncoded=",body)\n    if action is None:raise ValueError(\'shortcut-action-template\')\n    packed=base64.b64encode(gzip.compress(task_bytes,mtime=0)).decode()\n    reconstructed=action[1].replace("\'\'","\'")+packed+action[2].replace("\'\'","\'")\n    embedded=re.search(r"FromBase64String\\(\'([^\']+)\'\\)",reconstructed)\n    if embedded is None or gzip.decompress(base64.b64decode(embedded[1],validate=True))!=task_bytes:raise ValueError(\'shortcut-action-payload\')\n    if "$v.Length -ne "+str(len(task_bytes)) not in reconstructed or "-cne \'"+digest+"\'" not in reconstructed or "[IO.Compression.CompressionMode]::Decompress" not in reconstructed or "if($o.Length -gt 65536)" not in reconstructed or "[Text.UTF8Encoding]::new($false,$true).GetString($v)" not in reconstructed:raise ValueError(\'shortcut-action-consumer\')\n    encoded_action=base64.b64encode(reconstructed.encode(\'utf-16le\')).decode()\n    if base64.b64decode(encoded_action).decode(\'utf-16le\')!=reconstructed:raise ValueError(\'shortcut-action-command\')\n    helper_tree=ast.parse(helper_bytes);method=next(n for n in helper_tree.body if isinstance(n,ast.FunctionDef) and n.name==\'repair_program\')\n    expression=next(n.value for n in method.body if isinstance(n,ast.Assign) and isinstance(n.targets[0],ast.Name) and n.targets[0].id==\'loader\')\n    loader=eval(compile(ast.Expression(expression),\'authenticated-public-input-loader\',\'eval\'),{\'hashlib\':hashlib,\'str\':str,\'len\':len,\'__builtins__\':{}},{\'public\':full})\n    if values.get(\'ENCODED\')!=base64.b64encode(loader.encode(\'utf-16le\')).decode():raise ValueError(\'shortcut-loader-binding\')\n    compile(source,\'validated-complete-shortcut-packet\',\'exec\')\n    return True\n'
