class CompleteTaskInvocationPacketTests(HistoryCase):
 def namespace(self):
  ns={};exec(compile(SHORTCUT_PACKET_VALIDATOR_SOURCE+COMPLETE_TASK_INVOCATION_TRANSFORM_SOURCE+COMPLETE_TASK_INVOCATION_VALIDATOR_SOURCE,'complete-task-factory-validator','exec'),ns);return ns
 def test_actual_old_full_factory_to_complete_new_invocation_unchanged_task_consumers(self):
  case=ShortcutTaskPacketBindingTests();old=case.assemble();digest=hashlib.sha256(old[-1].encode()).hexdigest();fixedbody=old[-2].replace('a6262a588f0e0025174bfd4dbee8387a1dd9fd86e000e02f1a3b8be739af8c59',digest);ns=self.namespace();newbody=ns['_complete_task_invocation_body'](fixedbody);new=case.assemble(newbody,old[-1]);env,helper,source,sha,body,task=new
  self.assertTrue(ns['_validate_complete_task_packet'](source,sha,body,task,env['NONCE'],env['CORRELATION'],helper))
  for before,after in [(' -NonInteractive -Command ', ' -NonInteractive -Command - '),('Length -ge 30000','Length -ge 31000'),('[int]$cp117Character -eq 34','[int]$cp117Character -eq 0')]:
   badbody=newbody.replace(before,after);bad=case.assemble(badbody,old[-1]);env,helper,source,sha,body,task=bad
   with self.assertRaises(ValueError):ns['_validate_complete_task_packet'](source,sha,body,task,env['NONCE'],env['CORRELATION'],helper)
  with self.assertRaises(ValueError):ns['_complete_task_invocation_body'](newbody)

class CompleteTaskActionConstructorTests(HistoryCase):
 def test_actual_constructor_consumes_same_argument_that_is_hashed(self):
  case=CompleteTaskInvocationPacketTests(); ns=case.namespace()
  old=ShortcutTaskPacketBindingTests().assemble()
  task=old[-1]; digest=hashlib.sha256(task.encode()).hexdigest()
  body=ns['_complete_task_invocation_body'](old[-2].replace('a6262a588f0e0025174bfd4dbee8387a1dd9fd86e000e02f1a3b8be739af8c59',digest))
  import re
  match=re.search(r"^\$action=New-ScheduledTaskAction .*? -Argument ([^\r\n]+)$",body,re.M)
  self.assertIsNotNone(match)
  # Actual native b536 reached registration and compared this action with
  # cp117ActionSha, which is computed from cp117ActionArgument.
  self.assertEqual(match[1], '$cp117ActionArgument')

 @unittest.skipUnless(sys.platform=='win32','actual Windows ScheduledTasks action constructor required')
 def test_source_extracted_constructor_and_actual_argument_digest(self):
  import re,subprocess
  old=ShortcutTaskPacketBindingTests().assemble()
  ns=CompleteTaskInvocationPacketTests().namespace()
  body=ns['_complete_task_invocation_body'](old[-2])
  oldline=re.search(r"^\$action=New-ScheduledTaskAction [^\r\n]+$",old[-2],re.M)[0]
  newline=re.search(r"^\$action=New-ScheduledTaskAction [^\r\n]+$",body,re.M)[0]
  script="$ErrorActionPreference='Stop';$cp117ActionEncoded='PUBLIC_OLD';$cp117ActionArgument='-NoProfile -NonInteractive -Command '+[char]34+'PUBLIC_SOURCE'+[char]34;"
  digest="[BitConverter]::ToString([Security.Cryptography.SHA256]::Create().ComputeHash([Text.Encoding]::UTF8.GetBytes($action.Arguments))).Replace('-','').ToLowerInvariant()"
  script+="$expected=[BitConverter]::ToString([Security.Cryptography.SHA256]::Create().ComputeHash([Text.Encoding]::UTF8.GetBytes($cp117ActionArgument))).Replace('-','').ToLowerInvariant();"+oldline+";$old="+digest+";"+newline+";$new="+digest+";if($old -ceq $expected -or $new -cne $expected){throw 'ACTION_DIGEST'};[Console]::Out.WriteLine('ACTION_CONSTRUCTOR_PASS')"
  done=subprocess.run(['powershell','-NoProfile','-NonInteractive','-EncodedCommand',base64.b64encode(script.encode('utf-16-le')).decode()],capture_output=True,timeout=20)
  self.assertEqual(done.returncode,0,done.stderr.decode('utf-8','replace'));self.assertEqual(done.stdout.strip(),b'ACTION_CONSTRUCTOR_PASS')

