SHORTCUT_ACCESS_FACTORY_GZIP=''

class ShortcutAccessWholeFactoryTests(HistoryCase):
 def assemble(self,change_body=None,change_task=None):
  source=gzip.decompress(base64.b64decode(SHORTCUT_ACCESS_FACTORY_GZIP));tree=ast.parse(source)
  keys={'CORRELATION','NONCE','FIXED_BODY','FIXED_TASK'}
  ns={'ast':ast,'base64':base64,'hashlib':hashlib,'worker':refresh}
  for node in tree.body:
   if isinstance(node,ast.Assign)and isinstance(node.targets[0],ast.Name)and node.targets[0].id in keys:ns[node.targets[0].id]=ast.literal_eval(node.value)
  body=ns['FIXED_BODY'];task=ns['FIXED_TASK']
  if change_body:body=change_body(body)
  if change_task:task=change_task(task)
  ns['fixture']=lambda *_:(body,task)
  for name in ('_authenticated_access_validator','_validate_shortcut_packet','_complete_task_invocation_body','_validate_complete_task_packet','program'):
   node=next(n for n in tree.body if isinstance(n,ast.FunctionDef)and n.name==name);exec(compile(ast.Module(body=[node],type_ignores=[]),'actual-access-fullfactory','exec'),ns)
  raw=Path(__file__).read_bytes();helper=Path(refresh.__file__).read_bytes()
  result=ns['program'](ScreenTests().record(),raw,helper,b'')
  return ns,result
 def test_actual_complete_factory_closed_packet_validator_and_negative_consumers(self):
  ns,(source,sha,body,task)=self.assemble();self.assertLessEqual(len(source.encode()),131072);compile(source,'access-complete-carrier','exec')
  self.assertIn(refresh.installed.public._ps_literal(SHORTCUT_ACCESS_CHECK_CS),task)
  self.assertIn(SHORTCUT_ACCESS_READ_PS,task)
  compiled=ast.parse(source);actual=next(n for n in compiled.body if isinstance(n,ast.FunctionDef)and n.name=='_validate_access_observation');expected=ast.parse(SHORTCUT_ACCESS_VALIDATOR_SOURCE).body[0];self.assertEqual(ast.dump(actual),ast.dump(expected))
  for before,after in [('Cp117ShortcutAccess','Cp117ForeignAccess'),("GetBytes($action.Arguments)","GetBytes('FOREIGN')"),('Length -gt 65536','Length -gt 65537')]:
   if before=='Cp117ShortcutAccess':
    with self.assertRaises(ValueError):self.assemble(change_task=lambda x:x.replace(before,after))
   else:
    with self.assertRaises(ValueError):self.assemble(change_body=lambda x:x.replace(before,after))

