FULL_LOG_OLD_SERIALIZATION_CARRIER_GZIP=''

class FullLogCompleteSerializationTests(HistoryCase):
 def run_actual_chain(self,source):
  import io,contextlib
  tree=ast.parse(source);ns={'base64':base64,'hashlib':hashlib,'json':json};literal={}
  for node in tree.body:
   if isinstance(node,ast.Assign)and isinstance(node.targets[0],ast.Name)and node.targets[0].id in('D','NONCE','BODY_SHA'):
    literal[node.targets[0].id]=ast.literal_eval(node.value)
  for name in('validate','parse_terminal','result'):
   node=next(n for n in tree.body if isinstance(n,ast.FunctionDef)and n.name==name);exec(compile(ast.Module(body=[node],type_ignores=[]),'actual-complete-log-'+name,'exec'),ns)
  values=FullOriginalMsiLogTests();_,catalogue=values.functions();catalogue=dict(catalogue,CORRELATION=literal['D'],PARTS=[(literal['D'],literal['NONCE'])]);value=values.value(catalogue,0,b'PUBLIC'+b'x'*(8192-6))
  validator=next(n for n in tree.body if isinstance(n,ast.FunctionDef)and n.name=='validate');operation=next(n for n in ast.walk(validator)if isinstance(n,ast.Tuple)and len(n.elts)==2 and isinstance(n.elts[0],ast.Constant)and n.elts[0].value=='operationCorrelationId');value['operationCorrelationId']=ast.literal_eval(operation.elts[1])
  raw=('CP117-READ %s %s 8160\n'%(literal['NONCE'],literal['BODY_SHA'])).encode()+json.dumps(value,separators=(',',':')).encode();terminal={'exited':True,'exitcode':0,'out-truncated':False,'err-truncated':False,'out-data':base64.b64encode(raw).decode(),'err-data':''}
  answer=ns['parse_terminal'](terminal,literal['NONCE'],literal['BODY_SHA'],8160)
  output=io.StringIO()
  with contextlib.redirect_stdout(output):ns['result']({'state':'observed','facts':answer,'guestChildPid':8160,'appAdmission':False,'installerAction':False})
  return json.loads(output.getvalue()),value,ns,terminal,literal
 def test_actual_consumed_native_shaped_chain_red_and_current_complete_factory_green(self):
  old=gzip.decompress(base64.b64decode(FULL_LOG_OLD_SERIALIZATION_CARRIER_GZIP))
  with self.assertRaises(TypeError):self.run_actual_chain(old)
  caller,ns=FullOriginalMsiLogTests().functions();current=ns['program'](ScreenTests().record(),Path(__file__).read_bytes(),Path(refresh.__file__).read_bytes(),caller,0)[0]
  result,value,actual,terminal,literal=self.run_actual_chain(current);self.assertEqual(result['facts'],value);self.assertFalse(result['appAdmission']);self.assertFalse(result['installerAction'])
  for key,poison in [('exited',False),('exitcode',True),('exitcode',1),('out-truncated',True)]:
   changed=dict(terminal,**{key:poison})
   if key=='exited':self.assertIsNone(actual['parse_terminal'](changed,literal['NONCE'],literal['BODY_SHA'],8160))
   else:
    with self.assertRaises(ValueError):actual['parse_terminal'](changed,literal['NONCE'],literal['BODY_SHA'],8160)

