class MsiSourceIdentityTests(HistoryCase):
 def functions(self):
  ns={};exec(compile(MSI_SOURCE_IDENTITY_VALIDATOR_SOURCE+'\n'+SECURE_REPAIR_HISTORY_REFUSAL_SOURCE,'authenticated-source-diagnostic-test','exec'),ns);return ns
 def value(self):
  return {'version':1,'ordinaryActor':True,'aclPassed':True,'diagnosticCompleted':True,'credentialInput':False,'installerAction':False,'taskAction':True,'actor':{'pid':2832,'birth':'134356827285867566','sid':'S-1-5-21-2404255130-2183793310-3766671872-1002','sessionId':1,'limited':True},'observations':[{'index':i,'context':[1,2,4][i//6],'property':['LocalPackage','InstallSource','PackageCode','VersionString','LastUsedSource','PackageName'][i%6],'code':1605,'value':None}for i in range(18)],'contexts':[{'requested':i,'code':1605,'actual':0,'sid':None,'nextCode':259}for i in(1,2,4)],'sourceIdentityOnly':True,'repairAdmission':False,'currentBaseIdentity':':'.join(['1']*11),'currentBaseSha256':refresh.BASE_HASH,'msiFileHash':{'code':0,'a':1,'b':2,'c':3,'d':4}}
 def test_exact_finite_projection_and_unavailable(self):
  check=self.functions()['_validate_msi_source_observation'];v=self.value();self.assertIs(check(v),v)
  for mutate in [lambda x:x.update(repairAdmission=True),lambda x:x.update(version=True),lambda x:x['actor'].update(pid=True),lambda x:x['observations'][0].update(context=4),lambda x:x['observations'][1].update(value='invented'),lambda x:x['msiFileHash'].update(code=1)]:
   bad=copy.deepcopy(v);mutate(bad)
   with self.assertRaises(ValueError):check(bad)
 def test_actual_old_selector_then_native_history_refusal(self):
  admission=refresh.repair_admission(RepairSetupTests().census_value());self.assertEqual(admission['state'],'ready')
  history={'fullSha256':'0f6d15d56001037c69ca8d16368993b991a6abcbc9528b446554ea150bdaad68','bytes':245600,'hashMismatchLine':883,'secureRepairFailureLine':889,'shortcutFailureLine':891,'hashMismatch':True,'secureRepairFailed':True,'shortcutPathKnown':False}
  with self.assertRaisesRegex(ValueError,'historical-secure-repair-refusal'):self.functions()['_refuse_failed_source_recache'](admission,history)
  for key,bad in [('fullSha256','0'*64),('hashMismatch',1),('shortcutPathKnown',True)]:
   changed=dict(history);changed[key]=bad
   with self.assertRaisesRegex(ValueError,'source-history-pin'):self.functions()['_refuse_failed_source_recache'](admission,changed)

