class MsiSourceCompleteFactoryTests(HistoryCase):
 def namespace(self):
  source=Path(__file__).read_bytes();ns={'worker':refresh,'ast':ast,'hashlib':hashlib,'base64':base64,'Path':Path,'TEST_SHA':hashlib.sha256(source).hexdigest(),'FIXED_BODY':MSI_SOURCE_BODY,'FIXED_TASK':MSI_SOURCE_TASK,'CORRELATION':'aae95b8c-4ee3-4956-94d7-ef122d431f95','NONCE':'524c2c26-7ee2-4546-ad6d-aa9dbcd28ac3'}
  # Complete actual factory uses exact existing source-authenticated carrier/control functions.
  functions=[SHORTCUT_LOCAL_BIRTH_SOURCE,SHORTCUT_STDIN_COMMAND_SOURCE,SHORTCUT_STDIN_STREAM_SOURCE,SHORTCUT_PACKET_VALIDATOR_SOURCE,COMPLETE_TASK_INVOCATION_TRANSFORM_SOURCE,COMPLETE_TASK_INVOCATION_VALIDATOR_SOURCE,MSI_SOURCE_IDENTITY_VALIDATOR_SOURCE]
  payload='\n'.join(functions)+ '\n'+MSI_SOURCE_FACTORY_SOURCE
  exec(compile(payload,'actual-complete-msi-source-factory','exec'),ns);return ns,payload.encode(),source
 def test_actual_complete_factory_and_source_hash_packet(self):
  ns,caller,test=self.namespace();helper=Path(refresh.__file__).read_bytes();source,sha,body,task=ns['program'](ScreenTests().record(),test,helper,caller)
  compile(source,'actual-source-carrier','exec');self.assertLessEqual(len(source.encode()),131072);self.assertEqual(body,MSI_SOURCE_BODY);self.assertEqual(task,MSI_SOURCE_TASK)
  tasksha=hashlib.sha256(task.encode()).hexdigest();self.assertEqual(body.count(tasksha),4)
  self.assertIn(refresh.installed.public._ps_literal(MSI_SOURCE_IDENTITY_CS),task)
  self.assertIn('MsiGetProductInfoExW',task);self.assertNotIn('MsiConfigureProduct',task);self.assertNotIn('MsiSourceListSetInfo',task)

