class MsiSourcePacketRefusalTests(HistoryCase):
 def test_actual_complete_packet_rejects_stale_consumer_and_sha(self):
  for transform in [lambda b:b.replace('.Length -ne 21109','.Length -ne 25549'),lambda b:b.replace("taskSourceSha256='","taskSourceSha256='0",1)]:
   ns,caller,test=MsiSourceCompleteFactoryTests().namespace();changed=transform(ns['FIXED_BODY'])
   # Discover actual task byte length, never guess consumer length.
   if changed==ns['FIXED_BODY']:changed=ns['FIXED_BODY'].replace('.Length -ne '+str(len(ns['FIXED_TASK'].encode())),'.Length -ne 25549')
   self.assertNotEqual(changed,ns['FIXED_BODY']);ns['FIXED_BODY']=changed
   with self.assertRaises(ValueError):ns['program'](ScreenTests().record(),test,Path(refresh.__file__).read_bytes(),caller)
 def test_max_finite_output_fits_unchanged_projection_cap(self):
  v=MsiSourceIdentityTests().value()
  for row in v['observations']:row.update(code=0,value='P'*512)
  self.assertLessEqual(len(json.dumps(v,separators=(',',':')).encode()),16384)
  MsiSourceIdentityTests().functions()['_validate_msi_source_observation'](v)

# TEST-001: saved40757995 native failure SOURCE_BASE_SHA (62B,80b2b9b7...)
# belongs to originalaae95, not the recovery observer. Preserve that failed task.
def _repair_msi_source_task(task):
 for before,after in [("if($baseBefore[1] -cne '"+refresh.BASE_HASH+"'){throw 'SOURCE_BASE_SHA'}","if($baseBefore[0] -cne '"+refresh.BASE_HASH+"'){throw 'SOURCE_BASE_SHA'}"),('currentBaseIdentity=$baseBefore[0]','currentBaseIdentity=$baseBefore[1]'),('currentBaseSha256=$baseBefore[1]','currentBaseSha256=$baseBefore[0]')]:
  if task.count(before)!=1:raise ValueError('source-tuple-transform')
  task=task.replace(before,after)
 return task
MSI_SOURCE_REPAIRED_TASK=_repair_msi_source_task(MSI_SOURCE_TASK)
class MsiSourceTupleConsumerTests(HistoryCase):
 def actual_producer_expression(self):
  # Execute the actual return expression in the closest portable seam. Native
  # filesystem hashing/identity APIs are executed separately on Windows below.
  method=refresh.installed.FILE_CS.split('public static string[] Read(string path){',1)[1].split('public static string Runtime',1)[0]
  expression=re.findall(r'return new string\[\]\{([^}]+)\};',method)
  self.assertEqual(len(expression),1)
  names=expression[0].split(',');self.assertEqual(set(names),{'hash','first'})
  retained={'hash':refresh.BASE_HASH,'first':'3996455293:1441792:98853:664289174:31282281:0:131101044:32:655066335:31282281:1'}
  return [retained[name]for name in names]
 def apply_actual_consumer(self,task,values):
  gate=re.findall(r"if\(\$baseBefore\[([0-9]+)\] -cne '([0-9a-f]{64})'\)\{throw 'SOURCE_BASE_SHA'\}",task)
  self.assertEqual(len(gate),1)
  if values[int(gate[0][0])]!=gate[0][1]:raise ValueError('SOURCE_BASE_SHA')
  projections={key:int(index)for key,index in re.findall(r'(currentBaseIdentity|currentBaseSha256)=\$baseBefore\[([0-9]+)\]',task)}
  self.assertEqual(set(projections),{'currentBaseIdentity','currentBaseSha256'})
  return {key:values[index]for key,index in projections.items()}
 def test_archived_actual_producer_consumer_reproduces_saved_failure(self):
  with self.assertRaisesRegex(ValueError,'^SOURCE_BASE_SHA$'):self.apply_actual_consumer(MSI_SOURCE_TASK,self.actual_producer_expression())
 def test_fixed_actual_producer_guard_and_projection_reaches_strict_fact_parser(self):
  values=self.actual_producer_expression();facts=MsiSourceIdentityTests().value();facts.update(self.apply_actual_consumer(MSI_SOURCE_REPAIRED_TASK,values));parsed=MsiSourceIdentityTests().functions()['_validate_msi_source_observation'](facts)
  self.assertEqual(parsed['currentBaseSha256'],refresh.BASE_HASH);self.assertEqual(parsed['currentBaseIdentity'],values[1])
  for malformed in [[values[1],values[0]],['0'*64,values[1]]]:
   with self.assertRaises(ValueError):self.apply_actual_consumer(MSI_SOURCE_REPAIRED_TASK,malformed)
 @unittest.skipUnless(sys.platform=='win32','actual Windows FILE_CS tuple producer and PowerShell consumer')
 def test_actual_native_producer_and_old_new_consumer(self):
  scripts=[]
  for name,task in [('old',MSI_SOURCE_TASK),('new',MSI_SOURCE_REPAIRED_TASK)]:
   gate=re.search(r"if\(\$baseBefore\[[0-9]+\] -cne '[0-9a-f]{64}'\)\{throw 'SOURCE_BASE_SHA'\}",task).group()
   gate=gate.replace(refresh.BASE_HASH,"'+$expected+'")
   # Only expected fixture hash/path differ; actual producer and consumer index
   # semantics execute without mocks of the return array or native file APIs.
