  expression=region[region.index('if(')+3:region.index('{break}')].rstrip(')')
  # Preserve inner parentheses; remove only the outer if closing delimiter.
  condition=region[region.index('if(')+3:region.index('{break}')][:-1]
  for before,after in [('$status.State.ToString()','status'),('-ceq','=='),('-and','and'),('-or','or'),('[IO.File]::Exists($scratchPath)','scratch'),('[IO.File]::Exists($failurePath)','failure')]:condition=condition.replace(before,after)
