  allowed=(ast.Expression,ast.BoolOp,ast.Compare,ast.Name,ast.Load,ast.Constant,ast.And,ast.Or,ast.Eq)
  self.assertTrue(all(isinstance(n,allowed)for n in ast.walk(tree)))
