class BaselineReplacementCommandTests(HistoryCase):
 def arguments(self,source,msi="C:\\PUBLIC\\base.msi",root="C:\\PUBLIC"):
  # Execute the emitted closed argument expression, with only public fixture
  # paths substituted. Reject any token outside its literal concatenation.
  expression=re.search(r"\$phase='installer';\$arguments=([^\n]+)",source).group(1)
  token=re.compile(r"'([^']*)'|\$msi|\(Join-Path \$root '([^']+)'\)")
  values=[];offset=0
  while offset<len(expression):
   match=token.match(expression,offset)
   if match is None:raise ValueError('argument-expression')
   if match.group(1)is not None:values.append(match.group(1))
   elif match.group(2)is not None:values.append(root+'\\'+match.group(2))
   else:values.append(msi)
   offset=match.end()
   if offset<len(expression):
    if expression[offset]!='+':raise ValueError('argument-operator')
    offset+=1
  return ''.join(values)
 def candidate(self,phase):
  factory=getattr(refresh,'replacement_task',None)
  return refresh.repair_task() if factory is None else factory(phase,'10101010-1010-4010-8010-101010101010','20202020-2020-4020-8020-202020202020','a'*64 if phase=='provision'else None)
 def test_actual_equal_product_factory_must_retire_instead_of_silent_repair(self):
  old=RefreshTests().value();old['facts']['metadata']['oldProductCode']=refresh.REPAIR_PRODUCT;old['facts']['metadata']['staged']['productCode']=refresh.REPAIR_PRODUCT
  self.assertEqual(refresh.setup_plan(old)['branch'],'repair')
  emitted=self.arguments(self.candidate('retire'))
  self.assertEqual(emitted.split()[0],'/x')
  self.assertIn(refresh.REPAIR_PRODUCT,emitted)
  self.assertNotIn('REINSTALL',emitted)
 def test_actual_provision_argument_expression_has_fresh_install_semantics(self):
  emitted=self.arguments(self.candidate('provision'))
  self.assertEqual(emitted.split()[0],'/i');self.assertNotIn('REINSTALL',emitted)
  self.assertIn('ALLUSERS=2 MSIINSTALLPERUSER=1',emitted)

