  with tempfile.TemporaryDirectory()as leaf:
   root=Path(leaf).resolve(strict=True);base=root/'.runtime/parity-evidence';ret=base/('windows-refresh-repair-inert-'+corr);col=base/'windows-baseline-completion-3be5f5ef-60b0-4f3e-a4ed-f31886dd6b94';ret.mkdir(parents=True);col.mkdir()
