   ns={'worker':refresh,'json':json,'hashlib':hashlib,'Path':Path,'RETIREMENT_PROOF':proof,'WORKSPACE_SHA':proof['workspaceSha256'],'RETIREMENT_NONCE':nonce,'HELPER_SHA':'1'*64,'TEST_SHA':'2'*64,'RETIREMENT_CALLER_SHA':'3'*64};exec(compile(REPLACEMENT_RETIREMENT_PREFLIGHT_SOURCE,'actual-full-held-gate','exec'),ns)
   answer=ns['_retirement_preflight'](root,bound,Capture(),{});self.assertIs(answer['retirementCompleted'],True);self.assertIs(answer['currentVmAdmission'],False);self.assertIs(answer['installerAction'],False)
