 def test_actual_stale_admission_then_unchanged_recovered_guard(self):
  import types,io,stat
  record=self.actual_record();source,args=refresh.stage_program(record)
  current=(args[1],args[5],int(args[6]),int(args[7]),args[8])
  stale=('windows-cp117','/home/kardinal/vpn-control-windows-msi-acceptance-cp117/cp135-launch/qga.sock',589342,520739,current[4])
  transfer_record=dict(environment=current[0],socketPath=current[1],qemuPid=current[2],startTicks=current[3],expectedSid=current[4])
  # Actual legacy production comparison rejects before git/artifact/effects.
  with patch.object(refresh.transfer.base,'_descriptor',return_value=(None,types.SimpleNamespace(fixture_transfer_root=refresh.FIXTURE_ROOT),stale)),patch.object(refresh.transfer.subprocess,'run')as effect:
   with self.assertRaisesRegex(refresh.transfer.WindowsMsiHttpTransferError,'generation changed'):
    refresh.transfer._admit_current(Path('.'),transfer_record,Path(refresh.FIXTURE_ROOT))
   effect.assert_not_called()
  tree=ast.parse(source);node=next(n for n in tree.body if isinstance(n,ast.FunctionDef)and n.name=='live')
  # Complete actual live producer from full guarded carrier; unchanged base
