 def test_complete_readonly_factories_and_strict_listener_catalogue(self):
  import tempfile
  with tempfile.TemporaryDirectory()as td:
   path=Path(td).resolve()/'factory.py';path.write_text(DIRECT_FIXTURE_READBACK_FACTORY_SOURCE);path.chmod(0o600);n=self.factory(path);record=DirectRecoveredGenerationTests().actual_record()
   source,sha,args=n['download_program'](record,54935);listener=n['listener_program'](record);body,_=n['download_body'](54935)
   for value in (source,listener):compile(value,'complete-readback','exec');self.assertLessEqual(len(value.encode()),131072);n['_stdin_shortcut_command'](value)
   self.assertEqual(sha,hashlib.sha256(body.encode('utf-16le')).hexdigest());self.assertEqual(args,n['SUBMITTED_ACTION_SHA'])
   # This body is a readback, not the old action bootstrap; syntax/native execution
   # remains a Windows-only gate below.
   for action in ('Register-ScheduledTask','Start-ScheduledTask','Unregister-ScheduledTask','OpenDatabase','SetAccessControl','Expand-Archive'):
    self.assertNotIn(action,body)
   self.assertEqual(n['admit_listener']({'state':'served','port':54935,'pathSha256':hashlib.sha256(n['ROUTE_PATH'].encode()).hexdigest()})['state'],'served')
   for bad in ({'state':'served','port':True,'pathSha256':'0'*64},{'state':'served','port':54936,'pathSha256':hashlib.sha256(n['ROUTE_PATH'].encode()).hexdigest()},{'state':'served','port':54935,'pathSha256':'0'*64},{'state':'unknown'}):
    with self.assertRaises(ValueError):n['admit_listener'](bad)
