  import tempfile
  from agent_tools.windows_diagnostic_authority_capture import AuthorityCapture
  from agent_tools import windows_cp117_fixture_recovery_short_socket as r
  with tempfile.TemporaryDirectory()as td:
   root=Path(td).resolve();leaf=root/'.runtime/parity-evidence/source';leaf.mkdir(parents=True,mode=0o700);cap=AuthorityCapture(root,'source')
   try:pin=cap.create('caller.py',b'PUBLIC_ORIGINAL_CALLER\n')
   finally:cap.close()
   path=leaf/'caller.py';actual=r.authority._read_bound_file(path,private=True);wrong=dict(actual,sha256=hashlib.sha256(b'PUBLIC_DIFFERENT_READBACK_CALLER\n').hexdigest());history={str(path):wrong}
   n={'Path':Path,'root':root,'HISTORY':history,'AuthorityCapture':AuthorityCapture,'r':r};exec(compile(DIRECT_FIXTURE_STAGE_HISTORY_BOUND_SOURCE,'actual-main-history-bound','exec'),n)
   with self.assertRaisesRegex(Exception,'local-content'):n['history_bound'](path)
   history[str(path)]=actual;self.assertEqual(n['history_bound'](path),actual)

